"""Focused unit tests for the --rare and --top count options and their helpers."""

import contextlib
import io
import json
import tempfile
import unittest

from wordstats.cli import main
from wordstats.rarewords import keep_rare
from wordstats.topwords import keep_top


class KeepRareTests(unittest.TestCase):
    def test_keeps_words_at_or_below_n(self):
        self.assertEqual(keep_rare({"a": 1, "b": 3, "c": 2}, 2), {"a": 1, "c": 2})

    def test_zero_keeps_nothing(self):
        self.assertEqual(keep_rare({"a": 1}, 0), {})

    def test_large_n_keeps_everything(self):
        self.assertEqual(keep_rare({"a": 5, "b": 6}, 9), {"a": 5, "b": 6})

    def test_input_not_mutated(self):
        counts = {"a": 1, "b": 3}
        keep_rare(counts, 1)
        self.assertEqual(counts, {"a": 1, "b": 3})


class KeepTopTests(unittest.TestCase):
    def test_keeps_most_frequent(self):
        self.assertEqual(keep_top({"a": 1, "b": 3, "c": 2}, 2), {"b": 3, "c": 2})

    def test_ties_broken_alphabetically(self):
        self.assertEqual(keep_top({"x": 2, "y": 2, "z": 1}, 2), {"x": 2, "y": 2})

    def test_zero_keeps_nothing(self):
        self.assertEqual(keep_top({"a": 1}, 0), {})

    def test_large_n_keeps_everything(self):
        self.assertEqual(keep_top({"a": 1, "b": 2}, 9), {"a": 1, "b": 2})

    def test_input_not_mutated(self):
        counts = {"a": 1, "b": 2}
        keep_top(counts, 1)
        self.assertEqual(counts, {"a": 1, "b": 2})


class CountOptionTests(unittest.TestCase):
    def write_sample(self, text):
        handle = tempfile.NamedTemporaryFile("w", suffix=".txt", delete=False)
        handle.write(text)
        handle.close()
        self.addCleanup(lambda: __import__("os").unlink(handle.name))
        return handle.name

    def run_main(self, argv):
        stdout = io.StringIO()
        stderr = io.StringIO()
        with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
            code = main(argv)
        return code, stdout.getvalue(), stderr.getvalue()

    def test_rare_option_filters(self):
        path = self.write_sample("dog cat dog bird")
        code, out, _ = self.run_main(["count", path, "--rare", "1"])
        self.assertEqual(code, 0)
        self.assertEqual(json.loads(out), {"cat": 1, "dog": 2} if False else {"cat": 1})

    def test_top_option_filters(self):
        path = self.write_sample("dog cat dog bird cat")
        code, out, _ = self.run_main(["count", path, "--top", "2"])
        self.assertEqual(code, 0)
        self.assertEqual(json.loads(out), {"cat": 2, "dog": 2})

    def test_options_combined(self):
        path = self.write_sample("dog cat dog bird cat bird fish")
        code, out, _ = self.run_main(["count", path, "--rare", "2", "--top", "1"])
        self.assertEqual(code, 0)
        self.assertEqual(json.loads(out), {"bird": 2})

    def test_rare_rejects_zero(self):
        path = self.write_sample("dog")
        with self.assertRaises(SystemExit) as ctx:
            self.run_main(["count", path, "--rare", "0"])
        self.assertEqual(ctx.exception.code, 2)

    def test_rare_rejects_non_integer(self):
        path = self.write_sample("dog")
        code, _, stderr = self.run_main(["count", path, "--rare", "abc"])
        self.assertEqual(code, 2)
        self.assertIn("positive integer", stderr)

    def test_top_rejects_non_integer(self):
        path = self.write_sample("dog")
        code, _, stderr = self.run_main(["count", path, "--top", "1.5"])
        self.assertEqual(code, 2)
        self.assertIn("positive integer", stderr)

    def test_top_rejects_negative(self):
        path = self.write_sample("dog")
        code, _, stderr = self.run_main(["count", path, "--top", "-1"])
        self.assertEqual(code, 2)
        self.assertIn("positive integer", stderr)


if __name__ == "__main__":
    unittest.main()

